  }
  function verdictBody(a, c) {
    var s = a.name + "'s shots scatter " + fmt(c.st.spread) + ' about their own centroid, so precision is '
      + (c.prec ? 'HIGH' : 'LOW') + '. Their mean distance from the bullseye is ' + fmt(c.st.meanDist)
      + ', so accuracy is ' + (c.acc ? 'HIGH' : 'LOW') + '. ';
    if (c.prec && c.acc) s += 'Repeatable and correct — the only pattern that is both.';
    else if (c.prec && !c.acc) s += 'A tight cluster in the wrong place: perfectly repeatable, completely wrong. This is systematic error (bias), and averaging more shots will never fix it.';
    else if (!c.prec && c.acc) s += 'The shots average out near the truth, but no single shot can be trusted — random error dominates.';
    else s += 'Neither repeatable nor correct; any near-centre hit here is luck, not skill.';
    return s;
  }

  /* ── text helper (bbox-based positioning) ─────────────────────── */
  function txt(g, str, x, y, opt) {
