<span style="font-size:11px;color:#555;margin-top:4px">Drag the black “new shot” dot from the tray in the figure onto any target to change that archer's ratings.</span>
<button onclick="trigger_resetShots()" style="margin-top:2px">↺ Reset all shots</button>
<span style="font-size:10.5px;color:#777;line-height:1.4;margin-top:4px">Precision = RMS scatter of an archer's shots about their own centroid. Accuracy = mean distance of shots from the bullseye. Both reported in units of the outer target radius R.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var BLUE = '#8E9BD4';
  var VW = 1200, VH = 620;
  var R0 = 94;                       // outer target radius (world units)
  var PREC_T = 45, ACC_T = 55;       // thresholds in world units

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, VW, VH);

  var gMain = draw.group();
  var gExtras = draw.group();
  var gCallout = draw.group();
  var gDrag = draw.group();

  var ORIG = {
    W: [[-28, -18], [20, -12], [-14, 38], [20, 35]],
    X: [[46, 140], [67, 132], [76, 147], [73, 169]],
    Y: [[94, -173], [-69, -91], [-108, 85], [81, 158]],
    Z: [[57, -160], [-59, -29], [45, 35], [40, 163]]
  };

  var archers = [
    { key: 'W', name: 'Archer W', color: '#1f77b4', shots: [] },
    { key: 'X', name: 'Archer X', color: '#ff7f0e', shots: [] },
    { key: 'Y', name: 'Archer Y', color: '#2ca02c', shots: [] },
    { key: 'Z', name: 'Archer Z', color: '#9467bd', shots: [] }
  ];
  function resetShots() {
    for (var i = 0; i < archers.length; i++) {
      archers[i].shots = ORIG[archers[i].key].map(function (p) { return [p[0], p[1]]; });
    }
  }
  resetShots();

  var state = { selected: -1, overlay: false, metrics: false, step: 0 };

  /* ── geometry helpers ─────────────────────────────────────────── */
  var PW = 282, PH = 412, PY = 58, PGAP = 16, PX0 = 10;
  function panelX(i) { return PX0 + i * (PW + PGAP); }
  function panelCX(i) { return panelX(i) + PW / 2; }
  var PCY = PY + 194;   // 252

  function fmt(v) { return (v / R0).toFixed(2) + 'R'; }

  function stats(shots) {
    var n = shots.length;
    if (!n) return { cx: 0, cy: 0, spread: 0, meanDist: 0, bias: 0, n: 0 };
    var mx = 0, my = 0, i;
    for (i = 0; i < n; i++) { mx += shots[i][0]; my += shots[i][1]; }
    mx /= n; my /= n;
    var sp = 0, md = 0;
    for (i = 0; i < n; i++) {
      sp += (shots[i][0] - mx) * (shots[i][0] - mx) + (shots[i][1] - my) * (shots[i][1] - my);
      md += Math.sqrt(shots[i][0] * shots[i][0] + shots[i][1] * shots[i][1]);
    }
    return { cx: mx, cy: my, spread: Math.sqrt(sp / n), meanDist: md / n, bias: Math.sqrt(mx * mx + my * my), n: n };
  }
  function classify(a) {
    var st = stats(a.shots);
    return { st: st, prec: st.spread <= PREC_T, acc: st.meanDist <= ACC_T };
  }
  function verdictTitle(c) {
    return (c.prec ? 'precise' : 'imprecise') + ' and ' + (c.acc ? 'accurate' : 'inaccurate');
  }
  function verdictBody(a, c) {
    var s = a.name + "'s shots scatter " + fmt(c.st.spread) + ' about their own centroid, so precision is '
      + (c.prec ? 'HIGH' : 'LOW') + '. Their mean distance from the bullseye is ' + fmt(c.st.meanDist)
      + ', so accuracy is ' + (c.acc ? 'HIGH' : 'LOW') + '. ';
    if (c.prec && c.acc) s += 'Repeatable and correct — the only pattern that is both.';
    else if (c.prec && !c.acc) s += 'A tight cluster in the wrong place: perfectly repeatable, completely wrong. This is systematic error (bias), and averaging more shots will never fix it.';
    else if (!c.prec && c.acc) s += 'The shots average out near the truth, but no single shot can be trusted — random error dominates.';
    else s += 'Neither repeatable nor correct; any near-centre hit here is luck, not skill.';
    return s;
  }

  /* ── text helper (bbox-based positioning) ─────────────────────── */
  function txt(g, str, x, y, opt) {
    opt = opt || {};
    var t = g.text(str).font({
      family: 'sans-serif', size: opt.size || 12,
      weight: opt.weight || 'normal', anchor: 'middle'
    }).fill(opt.fill || '#444');
    var b = t.bbox();
    var cx = x;
    if (opt.align === 'start') cx = x + b.width / 2;
    else if (opt.align === 'end') cx = x - b.width / 2;
    t.center(cx, y);
    if (opt.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.2, 'stroke-linejoin': 'round' });
    return t;
  }

  function starPts(cx, cy, ro, ri, n) {
    var out = [];
    for (var k = 0; k < 2 * n; k++) {
      var a = -Math.PI / 2 + k * Math.PI / n;
      var r = (k % 2 === 0) ? ro : ri;
      out.push((cx + r * Math.cos(a)).toFixed(2) + ',' + (cy + r * Math.sin(a)).toFixed(2));
    }
    return out.join(' ');
  }

  function drawTarget(g, cx, cy, R) {
    var s = R / R0;
    g.circle(2 * R).center(cx, cy).fill(BLUE);
    g.circle(2 * 72 * s).center(cx, cy).fill('#fff');
    g.circle(2 * 52 * s).center(cx, cy).fill(BLUE);
    g.circle(2 * 44 * s).center(cx, cy).fill('#fff');
    g.circle(2 * 32 * s).center(cx, cy).fill(BLUE);
  }

  function drawShot(g, x, y, color, size, info) {
    var el = g.polygon(starPts(x, y, size, size * 0.62, 8)).fill(color || '#000');
    if (info) {
      el.css('cursor', 'pointer');
      el.on('mousemove', function (e) { showTooltip(info, e); }).on('mouseleave', hideTooltip);
    }
    return el;
  }

  function drawArrow(g, x1, y1, x2, y2, color, showLabel) {
    var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy);
    if (L < 6) return;
    var ux = dx / L, uy = dy / L;
    var line = g.line(x1, y1, x2 - ux * 8, y2 - uy * 8)
      .stroke({ color: color, width: 1.8, dasharray: '7,5', linecap: 'round' });
    var ax = x2 - ux * 10, ay = y2 - uy * 10, px = -uy, py = ux;
    g.polygon([x2 + ',' + y2, (ax + px * 5) + ',' + (ay + py * 5), (ax - px * 5) + ',' + (ay - py * 5)].join(' '))
      .fill(color);
    line.css('cursor', 'pointer').on('mousemove', function (e) {
      showTooltip('bias: distance from this archer\'s centroid to the true centre = accuracy error', e);
    }).on('mouseleave', hideTooltip);
    if (showLabel && L > 34) {
      txt(g, 'bias', (x1 + x2) / 2 - uy * 12, (y1 + y2) / 2 + ux * 12,
        { size: 11, fill: color, weight: 'bold', halo: true });
    }
  }

  function drawMetrics(g, cx, cy, a, sc, color, withLabel) {
    var st = stats(a.shots);
    if (!st.n) return;
    g.line(cx - 11, cy, cx + 11, cy).stroke({ color: '#333', width: 1.2 });
    g.line(cx, cy - 11, cx, cy + 11).stroke({ color: '#333', width: 1.2 });
    var gx = cx + st.cx * sc, gy = cy + st.cy * sc;
    var sc2 = Math.max(6, st.spread * sc);
    var sp = g.circle(2 * sc2).center(gx, gy).fill('none')
      .stroke({ color: color, width: 1.6, dasharray: '6,5' });
    sp.css('cursor', 'pointer').on('mousemove', function (e) {
      showTooltip('spread = ' + fmt(st.spread) + ' — RMS scatter about the archer\'s own centroid (precision)', e);
    }).on('mouseleave', hideTooltip);
    var ring = g.circle(13).center(gx, gy).fill('none').stroke({ color: color, width: 2.4 });
    ring.css('cursor', 'pointer').on('mousemove', function (e) {
      showTooltip('centroid of ' + a.name + '\'s shots', e);
    }).on('mouseleave', hideTooltip);
    drawArrow(g, gx, gy, cx, cy, color, withLabel);
  }

  /* ── four-panel view ──────────────────────────────────────────── */
  function renderPanels() {
    for (var i = 0; i < 4; i++) {
      (function (i) {
        var a = archers[i], px = panelX(i), sel = (state.selected === i);
        var g = gMain.group();
        g.rect(PW, PH).move(px, PY).fill('#ffffff')
          .stroke({ color: sel ? '#2b6cb0' : '#555', width: sel ? 3.5 : 2 });
        var inner = g.group();
        var clip = draw.clip();
        clip.add(draw.rect(PW - 4, PH - 4).move(px + 2, PY + 2));
        inner.clipWith(clip);
        var cx = panelCX(i), cy = PCY;
        drawTarget(inner, cx, cy, R0);
        if (state.metrics) drawMetrics(inner, cx, cy, a, 1, '#111', true);
        for (var k = 0; k < a.shots.length; k++) {
          var s = a.shots[k];
          var d = Math.sqrt(s[0] * s[0] + s[1] * s[1]);
          drawShot(inner, cx + s[0], cy + s[1], '#000', 7,
            a.name + ' · shot ' + (k + 1) + ' — ' + fmt(d) + ' from the bullseye');
        }
        txt(g, a.name, cx, 490, { size: 17, fill: '#555' });
        g.css('cursor', 'pointer');
        g.on('click', function () { panelClick(i); });
        g.on('mousemove', function (e) {
          showTooltip('Click ' + a.name + ' to see its precision / accuracy rating', e);
        }).on('mouseleave', hideTooltip);
      })(i);
    }
  }

  /* ── overlay view ─────────────────────────────────────────────── */
  var OCX = 520, OCY = 262, OR = 103;
  function renderOverlay() {
    var g = gMain.group();
    g.rect(1000, PH).move(10, PY).fill('#ffffff').stroke({ color: '#555', width: 2 });
    drawTarget(g, OCX, OCY, OR);
    var sc = OR / R0;
    for (var i = 0; i < 4; i++) {
      (function (i) {
        var a = archers[i];
        var dim = (state.selected >= 0 && state.selected !== i);
        var ag = g.group().opacity(dim ? 0.22 : 1);
        if (state.metrics) drawMetrics(ag, OCX, OCY, a, sc, a.color, !dim);
        for (var k = 0; k < a.shots.length; k++) {
          var s = a.shots[k];
          var d = Math.sqrt(s[0] * s[0] + s[1] * s[1]);
          drawShot(ag, OCX + s[0] * sc, OCY + s[1] * sc, a.color, 6.5,
            a.name + ' · shot ' + (k + 1) + ' — ' + fmt(d) + ' from the bullseye');
        }
      })(i);
    }
    // legend
    txt(g, 'All four shot sets on one target', 880, 96, { size: 13, weight: 'bold', fill: '#444', align: 'start' });
    for (var j = 0; j < 4; j++) {
      (function (j) {
        var a = archers[j], c = classify(a), y = 130 + j * 62;
        var row = g.group().css('cursor', 'pointer');
        row.rect(300, 54).move(872, y - 18).radius(6)
          .fill(state.selected === j ? '#eef5fd' : '#ffffff')
          .stroke({ color: state.selected === j ? '#2b6cb0' : '#e2e5ea', width: 1.2 });
        row.circle(13).center(890, y - 1).fill(a.color);
        txt(row, a.name, 904, y - 1, { size: 13, weight: 'bold', fill: '#222', align: 'start' });
        txt(row, (c.prec ? 'precise' : 'imprecise') + ' · ' + (c.acc ? 'accurate' : 'inaccurate'),
          1160, y - 1, { size: 11.5, fill: c.prec && c.acc ? '#1a7f37' : '#b42318', align: 'end' });
        txt(row, 'spread ' + fmt(c.st.spread) + '   mean distance ' + fmt(c.st.meanDist),
          890, y + 20, { size: 11, fill: '#666', align: 'start' });
        row.on('click', function () { panelClick(j); });
        row.on('mousemove', function (e) { showTooltip('Focus ' + a.name, e); }).on('mouseleave', hideTooltip);
      })(j);
    }
    txt(g, 'Archer W', OCX, 490, { size: 13, fill: '#fff' }).opacity(0); // spacer keeps layout stable
  }

  /* ── tray + quadrant legend ───────────────────────────────────── */
  function renderTray() {
    gExtras.rect(410, 90).move(20, 508).radius(8).fill('#fafafa')
      .stroke({ color: '#c9ced6', width: 1.2, dasharray: '5,4' });
    txt(gExtras, 'Drag a shot onto a target', 44, 532, { size: 13.5, fill: '#555', align: 'start' });
    txt(gExtras, 'then watch that archer\'s precision and accuracy ratings change',
      44, 588, { size: 10.5, fill: '#888', align: 'start' });
    var dot = gExtras.polygon(starPts(60, 562, 8, 5, 8)).fill('#000').css('cursor', 'grab');
    txt(gExtras, 'new shot', 78, 562, { size: 12, fill: '#333', align: 'start' });
    dot.on('mousemove', function (e) { showTooltip('Drag me onto any target', e); })
      .on('mouseleave', hideTooltip);
    dot.on('pointerdown', startDrag);
  }

  function renderQuad() {
    var gx = 985, gy = 534, cw = 95, ch = 34;
    txt(gExtras, 'Precision vs accuracy', 866, 512, { size: 12.5, weight: 'bold', fill: '#555', align: 'start' });
    txt(gExtras, 'Accurate', gx + cw / 2, gy - 10, { size: 10.5, fill: '#666' });
    txt(gExtras, 'Not accurate', gx + cw + cw / 2, gy - 10, { size: 10.5, fill: '#666' });
    txt(gExtras, 'Precise', gx - 8, gy + ch / 2, { size: 10.5, fill: '#666', align: 'end' });
    txt(gExtras, 'Not precise', gx - 8, gy + ch + ch / 2, { size: 10.5, fill: '#666', align: 'end' });
    for (var r = 0; r < 2; r++) {
      for (var c = 0; c < 2; c++) {
        var names = [], hot = false;
        for (var i = 0; i < 4; i++) {
          var cl = classify(archers[i]);
          if (cl.prec === (r === 0) && cl.acc === (c === 0)) {
            names.push(archers[i].key);
            if (state.selected === i) hot = true;
          }
        }
        var x = gx + c * cw, y = gy + r * ch;
        gExtras.rect(cw, ch).move(x, y).fill(hot ? '#dceafa' : '#ffffff')
          .stroke({ color: hot ? '#2b6cb0' : '#ccd1d8', width: hot ? 2 : 1 });
        txt(gExtras, names.length ? names.join(', ') : '—', x + cw / 2, y + ch / 2,
          { size: 12, weight: 'bold', fill: names.length ? '#333' : '#aaa' });
      }
    }
  }

  /* ── callout ──────────────────────────────────────────────────── */
  function chip(g, x, y, w, h, label, good) {
    g.rect(w, h).move(x, y).radius(5)
      .fill(good ? '#e7f6ea' : '#fdecea')
      .stroke({ color: good ? '#8fd0a1' : '#f2b4ae', width: 1 });
    txt(g, label, x + w / 2, y + h / 2, { size: 11.5, weight: 'bold', fill: good ? '#1a7f37' : '#b42318' });
  }

  function renderCallout() {
    if (state.selected < 0) {
      txt(gCallout, 'Click a target to see its precision and accuracy rating', 600, 30, { size: 13, fill: '#8a8f97' });
      return;
    }
    var i = state.selected, a = archers[i], c = classify(a);
    var cx = state.overlay ? OCX : panelCX(i);
    cx = Math.max(195, Math.min(1005, cx));
    var bw = 360, bh = 48, bx = cx - bw / 2, by = 5;
    gCallout.rect(bw, bh).move(bx, by).radius(7).fill('#ffffff').stroke({ color: '#2b6cb0', width: 2 });
    txt(gCallout, a.name, bx + 12, by + 16, { size: 14, weight: 'bold', fill: '#14243a', align: 'start' });
    chip(gCallout, bx + 96, by + 6, 120, 21, 'Precision: ' + (c.prec ? 'HIGH' : 'LOW'), c.prec);
    chip(gCallout, bx + 224, by + 6, 120, 21, 'Accuracy: ' + (c.acc ? 'HIGH' : 'LOW'), c.acc);
    txt(gCallout, 'spread ' + fmt(c.st.spread) + '  ·  mean distance from centre ' + fmt(c.st.meanDist) + '  ·  n = ' + c.st.n,
      bx + 12, by + 37, { size: 10.5, fill: '#666', align: 'start' });
  }

  /* ── master render ────────────────────────────────────────────── */
  function render() {
    try { draw.defs().clear(); } catch (e) { }
    gMain.clear(); gExtras.clear(); gCallout.clear();
    if (state.overlay) renderOverlay(); else renderPanels();
    renderTray();
    renderQuad();
    renderCallout();
    syncButtons();
  }

  function syncButtons() {
    for (var i = 0; i < 4; i++) {
      var b = document.getElementById('btnA' + i);
      if (b) b.className = (state.selected === i) ? 'active' : '';
    }
    var bn = document.getElementById('btnAn');
    if (bn) bn.className = (state.selected < 0) ? 'active' : '';
  }

  function panelClick(i) {
    state.selected = i;
    render();
    var c = classify(archers[i]);
    showPopup(archers[i].name + ' — ' + verdictTitle(c), verdictBody(archers[i], c));
  }

  /* ── drag a new shot ──────────────────────────────────────────── */
  var dragging = false;
  function toSvg(e) {
    var pt = draw.node.createSVGPoint();
    pt.x = e.clientX; pt.y = e.clientY;
    return pt.matrixTransform(draw.node.getScreenCTM().inverse());
  }
  function startDrag(e) {
    e.preventDefault();
    dragging = true;
    hideTooltip();
    gDrag.clear();
    var p = toSvg(e);
    gDrag.polygon(starPts(p.x, p.y, 8, 5, 8)).fill('#000').opacity(0.85);
  }
  function moveDrag(e) {
    if (!dragging) return;
    var p = toSvg(e);
    gDrag.clear();
    gDrag.polygon(starPts(p.x, p.y, 8, 5, 8)).fill('#000').opacity(0.85);
  }
  function endDrag(e) {
    if (!dragging) return;
    dragging = false;
    var p = toSvg(e);
    gDrag.clear();
    var target = -1, rx = 0, ry = 0;
    if (state.overlay) {
      if (p.x > 20 && p.x < 1000 && p.y > PY && p.y < PY + PH) {
        target = state.selected >= 0 ? state.selected : 0;
        rx = (p.x - OCX) / (OR / R0); ry = (p.y - OCY) / (OR / R0);
      }
    } else {
      for (var i = 0; i < 4; i++) {
        if (p.x >= panelX(i) && p.x <= panelX(i) + PW && p.y >= PY && p.y <= PY + PH) {
          target = i; rx = p.x - panelCX(i); ry = p.y - PCY; break;
        }
      }
    }
    if (target >= 0) {
      if (archers[target].shots.length < 14) archers[target].shots.push([rx, ry]);
      state.selected = target;
      state.metrics = true;
      var mi = document.getElementById('showMetricsInput');
      if (mi) mi.checked = true;
      render();
      var c = classify(archers[target]);
      showPopup('New shot added to ' + archers[target].name,
        'Spread is now ' + fmt(c.st.spread) + ' (precision ' + (c.prec ? 'HIGH' : 'LOW') +
        ') and mean distance from the bullseye is ' + fmt(c.st.meanDist) + ' (accuracy ' + (c.acc ? 'HIGH' : 'LOW') +
        '). Notice how one wild arrow wrecks precision while barely moving the centroid, whereas sliding a whole cluster toward the bullseye changes accuracy and leaves precision untouched.');
    }
  }
  window.addEventListener('pointermove', moveDrag);
  window.addEventListener('pointerup', endDrag);

  /* ── UI handlers ──────────────────────────────────────────────── */
  window.toggle_overlayTargets = function (on) { state.overlay = !!on; render(); };
  window.toggle_showMetrics = function (on) { state.metrics = !!on; render(); };
  window.trigger_selectArcher = function (i) { state.selected = i; render(); };
  window.trigger_resetShots = function () { resetShots(); render(); };

  /* ── demo steps ───────────────────────────────────────────────── */
  var steps = [
    {
      t: 'Four archers, four patterns',
      n: 'Four archers each fired four arrows at the same target. Compare the patterns before reading any labels: which archer is "good"?',
      o: false, m: false, s: -1
    },
    {
      t: 'Archer W — precise and accurate',
      n: 'Archer W\'s shots are tightly grouped AND centred on the bullseye: repeatable and correct.',
      o: false, m: false, s: 0
    },
    {
      t: 'Archer X — precise but not accurate',
      n: 'Archer X\'s cluster is just as tight as W\'s, but sits entirely off the target. Reproducibility says nothing about correctness — this is systematic error.',
      o: false, m: false, s: 1
    },
    {
      t: 'Measure the two ideas separately',
      n: 'Centroid, dashed spread circle and bias arrow are now shown. Spread size = precision; arrow length from centroid to centre = accuracy. W: small spread, short arrow. X: small spread, long arrow.',
      o: false, m: true, s: 1
    },
    {
      t: 'Archers Y and Z — neither',
      n: 'Y and Z have large spread circles (poor precision) and their shots sit far from the bullseye on average (poor accuracy). Their occasional near-centre hit is luck, not skill.',
      o: false, m: true, s: 2
    },
    {
      t: 'Overlay for direct comparison',
      n: 'All four shot sets stacked on one target. Spread and offset can now be read at a glance: two tight clusters (one centred, one offset) and two diffuse scatters.',
      o: true, m: true, s: -1
    },
    {
      t: 'Add your own shot',
      n: 'Drag the "new shot" dot from the tray onto any target and watch the ratings update. One wild arrow ruins Archer W\'s precision; moving X\'s cluster onto the bullseye makes it accurate without changing its precision.',
      o: false, m: true, s: 0
    }
  ];

  function applyStep(i) {
    i = Math.max(0, Math.min(steps.length - 1, i));
    state.step = i;
    var s = steps[i];
    state.overlay = s.o; state.metrics = s.m; state.selected = s.s;
    var oi = document.getElementById('overlayTargetsInput');
    var mi = document.getElementById('showMetricsInput');
    if (oi) oi.checked = s.o;
    if (mi) mi.checked = s.m;
    var nar = document.getElementById('demoNarration');
    if (nar) nar.innerHTML = '<b>' + s.t + '</b><br>' + s.n;
    var lab = document.getElementById('stepLabel');
    if (lab) lab.textContent = 'Step ' + (i + 1) + ' / ' + steps.length;
    render();
  }
  window.nextStep = function () { applyStep(state.step + 1); };
  window.prevStep = function () { applyStep(state.step - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Precision (how tightly repeated measurements agree with each other) and accuracy (how close their center of mass is to the true value) are independent properties, so four archers can occupy all four combinations of the precision × accuracy matrix.
KEY INSIGHT (what students should walk away understanding): Precision is how well repeated measurements agree with each other; accuracy is how close their average sits to the truth — which is why a tight cluster can be completely wrong (X) and a wild scatter can be right on average (Y).
DEMO STEPS: 8 guided steps — implement the step player in #ui

